import { Component, ViewChildren, QueryList, ElementRef, ChangeDetectorRef, HostListener, inject, ChangeDetectionStrategy, effect, OnDestroy, NgZone, signal } from '@angular/core';
import { FeedDisplayComponent } from "../rt-components/feed-display/feed-display.component";
import { realtimeEventParams, DocumentTab, tabmodel } from '@rt/models';
import { ActivatedRoute, Router } from '@angular/router';
import { NgClass, NgTemplateOutlet } from '@angular/common';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { PreviewComponent } from '../../../../shared/components/myfiles/preview/preview.component';
import { Subject, Subscription } from 'rxjs';
import { DragDropModule } from '@angular/cdk/drag-drop';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { pdfToolOptions, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { ToolbarComponent } from '../../../../pdf/components/toolbar/toolbar.component';
import { RealtimeFacade } from '@rt/facades';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { TranscriptViewerComponent } from '../../transcript-viewer/transcript-viewer.component';
import { QFactIssuePanelComponent } from '../../../../pdf/components/qfact-issue-panel/qfact-issue-panel.component';
import { SelectionActionsService } from '../../../../shared/services/selection-actions/selection-actions.service';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';

@Component({
  selector: 'app-realtime-shell',
  standalone: true,
  imports: [
    FeedDisplayComponent, ButtonComponent, NgTemplateOutlet, PreviewComponent, DragDropModule, NgClass, FormsModule,
    MatButtonModule, MatMenuModule, MatCheckboxModule, MatTooltipModule, IconComponent, ToolbarComponent, TranslateModule, TranscriptViewerComponent,
    QFactIssuePanelComponent,
  ],
  templateUrl: './realtime-shell.component.html',
  styleUrl: './realtime-shell.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RealtimeShellComponent implements OnDestroy {
  public translate = inject(TranslateService);
  public facade = inject(RealtimeFacade);
  public readonly selectionActions = inject(SelectionActionsService);
  private cdr = inject(ChangeDetectorRef);
  private route = inject(ActivatedRoute);
  private socket = inject(SocketService);
  private cm = inject(CommonfunctionService);
  private ngZone = inject(NgZone);
  private router = inject(Router);

  /** Realtime session-closed modal. Fires when the live backend broadcasts
   *  `realtime-transcript-messages { event: 'SESSION-CLOSED', data: { data: { nSesid, nCaseid } } }`
   *  in response to a local script POSTing /session/sessionend. The frontend
   *  filters by nSesid/nCaseid so only the windows actually viewing the
   *  closed session see the popup. Mirrors the publish-transcript modal in
   *  individual-doc.component / mainheader.component. */
  showSessionClosedPopup: boolean = false;
  private sessionClosedSub?: Subscription;

  /** QFact left-panel open state. Mirrors the individual-doc / pdf.component
   *  behaviour: armed by the toolbar's QFact mode pill, also openable via
   *  the LEFT-edge tab strip. Stays closed in compare/feed-compare modes
   *  because the layout doesn't have room for the 277px overlay there. */
  qfactPanelOpen: boolean = false;

  /** Resolved issue records for the current QFact selection — emitted by
   *  qfact-issue-panel.selectedIssuesChange. Drives the badge count on the
   *  QFact tab so the user sees how many issues are armed at a glance. */
  selectedIssues: any[] = [];

  private qfactEffect = effect(() => {
    const qfOn = this.selectionActions.state().qf;
    const shouldBeOpen = qfOn && !this.compareMode && !this.compareEnabled;
    if (shouldBeOpen !== this.qfactPanelOpen) {
      this.qfactPanelOpen = shouldBeOpen;
      this.cdr.markForCheck();
    }
  });

  toggleQFactTab(): void {
    if (this.compareMode || this.compareEnabled) return;
    if (this.qfactPanelOpen) {
      this.qfactPanelOpen = false;
    } else {
      this.qfactPanelOpen = true;
      this.selectionActions.setQFact();
    }
  }

  /** Routes to the existing service handler in feed-display, which opens
   *  the side-modal-manager's issue-manage panel with QFact mode pre-enabled
   *  — same flow as individual-doc / pdf.component. */
  openQFactManage(): void {
    if (!this.nCaseid || !this.nUserid) return;
    this.selectionActions.requestOpenQFactManage();
  }

  @ViewChildren('embeddedIframe') embeddedIframes!: QueryList<ElementRef>;

  /** Live refs to every <feed-display> currently in the view. Used by the
   *  activeTab setter to transfer marknav visibility between the two
   *  split-mode panes when the user switches focus. ViewChildren tree
   *  order is stable (primary first, split second), matching activeTab
   *  values 1 and 2 respectively. */
  @ViewChildren(FeedDisplayComponent) feeds!: QueryList<FeedDisplayComponent>;

  // Core properties
  nCaseid: string = '';
  nSesid!: string;
  
  // UI State Getters (Signals)
  get nUserid() { return this.facade.user()?.nUserid || ''; }
  get sessionDetail() { return this.facade.sessionDetail; }
  get compareMode() { return this.facade.uiState().isCompareMode; } // PDF Comparison
  get compareEnabled() { return this.facade.uiState().isFeedCompare; } // Feed Comparison
  get splitScreenEnabled() { return this.facade.uiState().isSplitScreen; }
  get splitSessionId() { return this.facade.uiState().splitSessionId; }
  
  get compareSessionL() { return this.facade.compareState().sessionL; }
  get compareSessionR() { return this.facade.compareState().sessionR; }
  get compareDocumentList() { return this.facade.compareState().documentList; }
  get demoDoclist() { return this.facade.compareState().demoDocList; }
  get compareIndex() { return this.facade.compareState().currentIndex; }
  get isDemoStarted() { return this.facade.isDemoStarted(); }

  // Local UI State (Keep for now as they handle View specific interactions)
  isLoading: boolean = true;
  useCanonicalView: boolean = false; // Toggle between live feed and HTML-canonical view
  /** Active pane in split mode (1 = primary, 2 = split). Setter handles the
   *  marknav transfer described below. */
  private _activeTab: 1 | 2 = 1;
  get activeTab(): 1 | 2 { return this._activeTab; }
  set activeTab(tab: 1 | 2) {
    const previous = this._activeTab;
    if (previous === tab) return;

    // In split-screen mode the marknav panel is rendered by the pane that
    // opened it and positioned on the OPPOSITE side via the tabindex CSS
    // in feed-display.component.html. When the user switches focus to the
    // other pane (clicks it), transfer the marknav so it stays opposite
    // the user's active pane — without this, the panel is stuck on the
    // side it was opened on, sitting next to the wrong pane after a
    // pane-switch click.
    if (this.splitScreenEnabled && this.feeds) {
      const arr = this.feeds.toArray();
      const oldFeed = arr[previous - 1];
      const newFeed = arr[tab - 1];
      if (oldFeed?.visibleMarkNavModel && newFeed) {
        oldFeed.visibleMarkNavModel = false;
        newFeed.visibleMarkNavModel = true;
      }
    }

    this._activeTab = tab;
  }
  taborder: 1 | 2 = 1;
  fullViewMode: boolean = false;
  ispdfactive: boolean = false;
  selectedTab!: DocumentTab;
  tabBox: tabmodel | null = null;
  
  private eventPrimarySubject = new Subject<realtimeEventParams>();
  eventPrimary$ = this.eventPrimarySubject.asObservable();

  private eventPreviewSubject = new Subject<realtimeEventParams>();
  eventPreview$ = this.eventPreviewSubject.asObservable();
  
  toolBarOptions: pdfToolOptions = { pdfLoaded: false } as pdfToolOptions;

  viewlist: any = [];

  @HostListener('window:message', ['$event'])
  onPdf = async (event: MessageEvent) => {
    try {
      if (event.origin !== window.location.origin || !event.data.identity) {
        return;
      }
    
      const index: number = this.compareDocumentList.findIndex(a => a.nBundledetailid == event.data.identity);
      if (index == -1) {
        const data: toolEvents = event.data.message;
        if (data.event == 'COMPARE-DATA-UPDATE' && this.compareMode && this.selectedTab.nBundledetailid == event.data.identity) {
           // Logic to update local toolbar options? 
           // Or should this go to Facade? 
           // Keeping UI logic here for iframe messaging for now.
           // Updating the list in facade?
           // Accessing read-only signal list is fine.
          const currentList = [...this.compareDocumentList]; 
          const targetIndex: number = currentList.findIndex(a => a.nBundledetailid == event.data.identity);
           if (targetIndex > -1){
              if (data?.data?.currentPage == 1) {
                  data.data.currentPage = currentList[targetIndex].onPage || 1;
              }
              currentList[targetIndex] = { ...currentList[targetIndex], currentPage: data.data.currentPage || 1};
              this.facade.updateCompareDocumentList(currentList);
              this.updateCompareData(currentList[targetIndex], data.data);
           }
        }
        return
      };

      let x: DocumentTab = this.compareDocumentList[index];
      if (x) {
        const data: toolEvents = event.data.message
        if (data.event == 'COMPARE-DATA-UPDATE') {
             const currentList = [...this.compareDocumentList];
             currentList[index] = { ...currentList[index], currentPage: data.data.currentPage};
             this.facade.updateCompareDocumentList(currentList);
             this.updateCompareData(x, data.data);
        } else if (data.event == 'ZOOM') {
          this.toolBarOptions.zoom = data.data.zoom;
        } else if (data.event == 'CURRENT-PAGE') {
           const currentList = [...this.compareDocumentList];
           currentList[index] = { ...currentList[index], currentPage: data.data.currentPage};
           this.facade.updateCompareDocumentList(currentList);
           this.toolBarOptions.currentPage = data.data.currentPage;
        } else if (data.event == 'FULL_SCREEN_CHANGE') {
          this.cdr.detectChanges();
        } else if (data.event == 'FILTER-ANNOTATION') {
          this.sendMessageToIframe(x.nBundledetailid, data);
        }
      }
    } catch (error) {
      console.error('error in data of parent', error);
    }
  }

  constructor() {
    try {
      const params: any = this.route.snapshot.params;
      const data: { nCaseid: string, nSesid: string } = JSON.parse(atob(params.id));
      this.nCaseid = data.nCaseid;
      if (data?.nSesid)
        this.nSesid = data?.nSesid;
    } catch (error) {
       console.error('Error fetching params', error);
    }

    // Listen for realtime session-closed broadcasts. The full chain:
    //   1. Local script POSTs {nSesid, permission:'C'} to LIVE_SERVER/session/sessionend
    //      (D:\etabella-com-V2.2/main.js:561 → makePostRequest)
    //   2. Live backend's sessionEnd service emits `on-notification`
    //      with {msg:1, nSesid, cStatus:'E'} on the realtime socket
    //      (apps/realtime-server/src/services/session/session.service.ts:218)
    //   3. SocketService.getNotification() surfaces that here
    // The 'E' (Ended) cStatus is what we filter on; only show the modal when
    // the closed nSesid matches a session this shell currently has open
    // (primary / split / compare).
    this.sessionClosedSub = this.socket.getNotification().subscribe((res: any) => {
      const payload = res?.data?.data ?? res?.data ?? res ?? {};
      if (payload?.cStatus !== 'E') return;
      if (!this.matchesOpenSession(payload)) return;
      this.showSessionClosedPopup = true;
      this.cdr.detectChanges();
    });
  }

  /** True if the closed nSesid matches any session this shell currently has
   *  open (primary, split, or compare panes). The live backend always emits
   *  the nSesid with the close event, so we filter precisely. */
  private matchesOpenSession(payload: any): boolean {
    const closedSesid = payload?.nSesid != null ? String(payload.nSesid) : '';
    if (!closedSesid) return false;
    const open = [this.nSesid, this.splitSessionId, this.compareSessionL, this.compareSessionR]
      .filter(Boolean)
      .map(String);
    return open.includes(closedSesid);
  }

  /** Close the popup and route to Evidence > Transcripts for this case.
   *  The realtime view is typically opened in a popup window from the
   *  Evidence sidenav (sidenav.component.ts → window.open). When that's
   *  the case we tell the opener to navigate AND close this RT window —
   *  so the user lands directly in the Evidence module without an extra
   *  click or stale RT tab. If there's no opener (RT loaded directly),
   *  navigate in the current window. Same destination as the TS-PUBLISH
   *  client notification (notifications.component.ts:97-101). */
  openTranscriptFolder(): void {
    this.showSessionClosedPopup = false;
    if (!this.nCaseid) return;

    const opener = window.opener as Window | null;
    if (opener && !opener.closed) {
      try {
        opener.postMessage(
          { event: 'OPEN-TRANSCRIPT-FOLDER', nCaseid: this.nCaseid },
          window.location.origin
        );
        opener.focus();
        window.close();
        return;
      } catch {
        // postMessage / focus / close can throw if the opener was closed
        // between the check and the call — fall through to in-window nav.
      }
    }

    this.cm.goto('/myfiles/filesaction', { id: this.nCaseid });
  }

  // Doc viewer splitter drag-resize.
  //
  // Strategy: LIVE resize. The splitter sits on the panel's left edge, so as
  // the panel widens the splitter naturally moves with the cursor — cursor
  // and handle stay glued together.
  //
  // Pointer capture (setPointerCapture): every subsequent pointer event for
  // this pointer is routed to the captured element, regardless of what's
  // under the cursor. This is the fix for the "drag stays stuck" bug — if
  // the cursor passes over an iframe (the PDF viewer) or leaves the window,
  // a document-level `pointerup` listener never fires. With capture, the
  // splitter element itself receives pointerup wherever the user releases.
  //
  // Smoothness measures:
  //   * Listeners register via `ngZone.runOutsideAngular` so pointermove
  //     doesn't trigger zone-wide CD.
  //   * Pointermove writes are coalesced through requestAnimationFrame —
  //     one width update per frame regardless of OS pointer event rate.
  //   * `docResizing` signal toggles `will-change: width` on both panes so
  //     the browser pre-promotes them to their own composite layer.
  //   * localStorage persist runs once on pointer-up, not on every move.
  private docResizeStartX = 0;
  private docResizeStartRatio = 0;
  private docResizeRafId: number | null = null;
  private docResizePendingX = 0;
  private docResizePointerId: number | null = null;
  private docResizeHandle: HTMLElement | null = null;
  private docResizeMoveHandler?: (e: PointerEvent) => void;
  private docResizeEndHandler?: (e: PointerEvent) => void;

  docResizing = signal<boolean>(false);

  onDocResizeStart(ev: PointerEvent): void {
    ev.preventDefault();
    ev.stopPropagation();

    const handle = ev.currentTarget as HTMLElement | null;
    if (!handle) return;

    // Safety: if a previous drag didn't clean up (shouldn't happen, but
    // defensive against pointercancel etc), tear it down before starting.
    if (this.docResizing()) {
      this.teardownDocResize();
    }

    this.docResizeHandle = handle;
    this.docResizePointerId = ev.pointerId;
    this.docResizeStartX = ev.clientX;
    this.docResizeStartRatio = this.facade.docViewerRatio();
    this.docResizePendingX = ev.clientX;
    this.docResizing.set(true);
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'col-resize';

    // Route all subsequent pointer events for this pointer to the splitter
    // element, even when the cursor is over an iframe or off-window.
    try {
      handle.setPointerCapture(ev.pointerId);
    } catch {
      // setPointerCapture can throw if the pointer is no longer active —
      // non-fatal; we fall back to bubbling events on the element.
    }

    this.ngZone.runOutsideAngular(() => {
      this.docResizeMoveHandler = (e: PointerEvent) => this.onDocResizeMove(e);
      this.docResizeEndHandler = (e: PointerEvent) => this.onDocResizeEnd(e);
      // Bind directly to the handle — with pointer capture all events for
      // this pointer are dispatched here.
      handle.addEventListener('pointermove', this.docResizeMoveHandler);
      handle.addEventListener('pointerup', this.docResizeEndHandler);
      handle.addEventListener('pointercancel', this.docResizeEndHandler);
      // Belt-and-braces: if the browser releases capture for any reason
      // (e.g. context-menu, tab switch), treat it as drag-end so we don't
      // leave a stuck listener behind.
      handle.addEventListener('lostpointercapture', this.docResizeEndHandler);
    });
  }

  private onDocResizeMove(ev: PointerEvent): void {
    // Filter by pointerId so a second pointer (multi-touch) can't drive us.
    if (this.docResizePointerId !== null && ev.pointerId !== this.docResizePointerId) return;
    this.docResizePendingX = ev.clientX;
    if (this.docResizeRafId !== null) return;
    this.docResizeRafId = requestAnimationFrame(() => {
      this.docResizeRafId = null;
      const vw = window.innerWidth;
      if (!vw) return;
      const deltaPct = ((this.docResizeStartX - this.docResizePendingX) / vw) * 100;
      this.ngZone.run(() => {
        this.facade.setDocViewerRatio(this.docResizeStartRatio + deltaPct, false);
      });
    });
  }

  private onDocResizeEnd(ev: PointerEvent): void {
    if (this.docResizePointerId !== null && ev.pointerId !== this.docResizePointerId) return;
    this.teardownDocResize();
    this.ngZone.run(() => {
      this.facade.persistDocViewerRatio();
      this.docResizing.set(false);
    });
  }

  /** Idempotent cleanup of every resource a live drag holds. Safe to call
   *  from pointerup, pointercancel, lostpointercapture, ngOnDestroy, or as
   *  a defensive reset at the start of a new drag. */
  private teardownDocResize(): void {
    if (this.docResizeRafId !== null) {
      cancelAnimationFrame(this.docResizeRafId);
      this.docResizeRafId = null;
    }
    document.body.style.userSelect = '';
    document.body.style.cursor = '';

    const handle = this.docResizeHandle;
    if (handle) {
      if (this.docResizeMoveHandler) {
        handle.removeEventListener('pointermove', this.docResizeMoveHandler);
      }
      if (this.docResizeEndHandler) {
        handle.removeEventListener('pointerup', this.docResizeEndHandler);
        handle.removeEventListener('pointercancel', this.docResizeEndHandler);
        handle.removeEventListener('lostpointercapture', this.docResizeEndHandler);
      }
      if (this.docResizePointerId !== null) {
        try {
          if (handle.hasPointerCapture(this.docResizePointerId)) {
            handle.releasePointerCapture(this.docResizePointerId);
          }
        } catch {
          // non-fatal
        }
      }
    }

    this.docResizeMoveHandler = undefined;
    this.docResizeEndHandler = undefined;
    this.docResizeHandle = null;
    this.docResizePointerId = null;
  }

  ngOnDestroy(): void {
    this.sessionClosedSub?.unsubscribe();
    this.teardownDocResize();
    this.removeWarmupIframe();
  }

  async ngOnInit(): Promise<void> {
    // No local user fetch needed, facade handles it
    // Facade initializeSession calls getCaseDetail internally
    this.facade.initializeSession(this.nCaseid, this.nSesid).then(session => {
        if(session) this.nSesid = session;
        this.isLoading = false;
        this.cdr.detectChanges();
    });

    // Warm the lazy PdfModule chunk in the background so the first hyperlink
    // click in this session doesn't have to wait on its download. Best-effort —
    // if the route lookup or load fails, the normal click-time lazy load still
    // works.
    this.preloadViewerModule();

    // Warm the /viewer/pdf iframe shell (Angular bundle, NgxExtendedPdfViewer,
    // PDF.js worker script). The visible preview iframe spins up a fresh
    // worker on the first hyperlink click, but with the JS and CSS assets
    // already in the browser cache that boot drops from ~1–2s to ~300–500ms.
    this.warmupPdfViewer();
  }

  private preloadViewerModule(): void {
    setTimeout(() => {
      const viewerRoute = this.router.config.find(r => r.path === 'viewer');
      if (viewerRoute && typeof viewerRoute.loadChildren === 'function') {
        const result = (viewerRoute.loadChildren as () => unknown)();
        if (result && typeof (result as Promise<unknown>).then === 'function') {
          (result as Promise<unknown>).catch(() => { /* non-critical */ });
        }
      }
    }, 1500);
  }

  private warmupIframeId = 'rt-pdf-warmup-iframe';

  private warmupPdfViewer(): void {
    setTimeout(() => {
      try {
        if (typeof document === 'undefined') return;
        if (document.getElementById(this.warmupIframeId)) return;
        const iframe = document.createElement('iframe');
        iframe.id = this.warmupIframeId;
        // Encoded path is intentionally a placeholder — the page will 404 the
        // PDF binary but still bootstrap the entire Angular viewer shell and
        // PDF.js worker script, which is all we need to cache.
        iframe.src = '/viewer/pdf/' + btoa('warmup') + '?warm=1';
        iframe.style.cssText = 'position:fixed;left:-10000px;top:0;width:1px;height:1px;opacity:0;pointer-events:none;border:0;';
        iframe.tabIndex = -1;
        iframe.title = 'PDF viewer warmup';
        iframe.setAttribute('aria-hidden', 'true');
        document.body.appendChild(iframe);
      } catch {
        // Non-critical — viewer still works on click-time lazy load.
      }
    }, 2500);
  }

  private removeWarmupIframe(): void {
    try {
      const el = document.getElementById(this.warmupIframeId);
      if (el?.parentNode) el.parentNode.removeChild(el);
    } catch {
      // non-critical
    }
  }

  handleRealttimeEvents(e: realtimeEventParams, primary: boolean = false) {
    if (e.type == 'COMPARE-MODE-ENABLED') {
      this.facade.enableFeedCompare(e.data.selectedSessionL, e.data.selectedSessionR);
      this.activeTab = 2; // Set focus to right tab if needed, logic from old component
    } else if (e.type == 'COMPARE-MODE-CLOSED') {
      this.facade.disableFeedCompare();
      this.activeTab = 1;
    } else if (e.type == 'SWITCH-MODE-ENABLED') {
       this.facade.enableSwitchMode(e.data?.nSesid);
    } else if (e.type == 'SWITCH-MODE-DISABLE') {
       this.facade.disableSwitchMode();
    } else if (e.type == 'FULL-VIEW-MODE-CHANGED') {
      this.fullViewMode = e.data;
    } else if (e.type == 'HYPERLINK-CLICK') {
      this.tabBox = e.data;
      this.cdr.detectChanges(); // Immediately propagate tabBox to preview → starts API call
      setTimeout(() => {
        this.ispdfactive = true;
        this.cdr.detectChanges();
      }, 100);
    } else if (e.type == 'OPEN-COMPARE-MODE') {
      this.facade.handleOpenCompareMode(e.data);
    }
    
    // Preview Event Handling
    if (e.type == 'FEED-UPDATED') {
      this.eventPreviewSubject.next(e);
    }

    // Annotation sync: forward QFact/Fact annotations to secondary panel
    if (e.type == 'ANNOT-SYNCED') {
      this.eventPreviewSubject.next(e);
    }
  }

  // UI Helper Methods
  switchActiveTab() {
    this.taborder = this.taborder == 1 ? 2 : 1
  }

  // Display Event Handlers
  onFeedDisplayEvent(event: any, primary = false) {
    // Placeholder as in original
  }

  OnEvent(e: any) {
    if (e.event == 'CLOSE_REALTIME') {
      this.tabBox = null;
    }
  }
  
  get calculatedWidthPx(): string {
      // Legacy visual logic, keeping for now or move to directive later
    const baseValue = 956;
    const incrementPercentage = 1; 
    const totalValue = window.screen.width; 
    const calculatedValue = baseValue * incrementPercentage;
    const remainingValue = totalValue - calculatedValue;
    return `${remainingValue}px`;
  }



  selectCompare(x: DocumentTab, i: number) {
    this.selectedTab = x;
    this.facade.setCompareIndex(i + 1);
    this.fetchCompareToolData(x);
    this.cdr.detectChanges();
  }

  fetchCompareToolData(x: DocumentTab) {
    this.sendMessageToIframe(x.nBundledetailid, { event: 'FETCH-COMPARE-TOOL-DATA', data: {} }, this.compareIndex);
  }

  onLoadEnd(e: any, x: DocumentTab) {
  }

  sendMessageToIframe(nBundledetailid: string, data: any, index?: number) {
    const iframeElement = this.embeddedIframes?.find((iframeRef: ElementRef) =>
      iframeRef.nativeElement.id === `iframe${index ? index : ''}-${nBundledetailid}`);
    if (iframeElement) {
      iframeElement.nativeElement.contentWindow.postMessage(data, '*');
    }
  }

  onSelectingDoc(item: DocumentTab, event: any) {
    if (event.checked) {
      if (this.compareDocumentList.length < 4) {
        const existingIndex = this.compareDocumentList.findIndex(doc => doc.nBundledetailid === item.nBundledetailid);
        if (existingIndex === -1) {
            // Need senitizeUrl here? It's internal to Facade. 
            // We should add a method in Facade to "addDocumentToCompare(item)".
            // For now, since I can't call senitizeUrl, I MUST implement addDocumentToCompare in Facade.
            // But wait, the list is readonly. I can't push to it locally.
            // So logic MUST be in Facade.
            // I will assume facade.addDocumentToCompare(item) exists or I will create it.
            // For this step, I will comment it out and add todo, OR better, create the method in Facade NEXT.
            // Actually, I can allow the user to select docs, passing the event to Facade.
            // facade.toggleCompareDocument(item, checked)
        }
      }
    } else {
        // facade.removeCompareDocument(item)
    }
    // Simplification: call facade.
    this.facade.handleDocumentSelectionChange(item, event.checked); 
    this.cdr.detectChanges();
  }


  onToolEvents(e: toolEvents) {
    if (e.event == 'TOOLBAR-PDF-NAV-EVENTS') {
      this.sendMessageToIframe(this.selectedTab.nBundledetailid, { event: 'TOOL-CHANGE-EVENTS', data: e.data }, this.compareIndex);
      return;
    }

    if (e.event == 'CLOSE_REALTIME') {
      this.facade.disableCompareMode();
    }

    if (e.event == 'COMPARE_MODE') {
      if (!e.data) {
        this.facade.setCompareMode(!this.compareMode);
        this.cdr.detectChanges();
      }
      return;
    }

    if (e.event == 'CLEAR-PDF-SEARCH') {
      this.compareDocumentList.forEach((a, index) => {
        if (this.compareIndex != (index + 1)) {
          this.sendMessageToIframe(a.nBundledetailid, { event: 'CLEAR-PDF-SEARCH', data: {} }, index + 1);
        };
      });
    }

    this.sendMessageToIframe(this.selectedTab.nBundledetailid, { event: 'COMPARE-TOOL-CHANGE-EVENT', data: e }, this.compareIndex);
  }

  updateCompareData(x: any, data: pdfToolOptions) {
    this.toolBarOptions = data;
    this.cdr.detectChanges();
  }

  async onSessionSwitch(newSessionId: string) {
    if (this.nSesid !== newSessionId) {
      // Safety: ensure demo state is cleared when switching sessions
      if (this.facade.isDemoStarted()) {
        this.facade.resetDemoState();
      }

      // Re-initialize session via facade and wait for completion
      await this.facade.initializeSession(this.nCaseid, newSessionId);
      // Now update local state, ensuring sessionDetail signal is already ready
      this.nSesid = newSessionId;
      this.cdr.detectChanges();
    }
  }

}
